import LexGrammar   ( Token, mkPosToken )
import ParGrammar   ( pDeclarations, myLexer )
import PrettyPrinter  ( Print(..) )
import qualified StatSem.Mod as SS
import qualified TAC.Gen     as TAC
import qualified TAC.Printer()
import qualified AbsSyn      as AS

type Err        = Either String
type ParseFun a = [Token] -> Err a
type Verbosity  = Int

putStrV :: Verbosity -> String -> IO ()
putStrV v s = when (v > 1) $ putStrLn s

runFile :: Verbosity -> ParseFun (AS.Declarations ()) -> FilePath -> IO ()
runFile v p f = readFile f >>= \s -> run v p s (Just f)

run :: Verbosity -> ParseFun (AS.Declarations ()) -> String -> Maybe FilePath -> IO ()
run v p s f =
    case p ts of
        Left err -> do
            putStrLn "\nParse              Failed...\n"
            putStrV v "Tokens:"
            mapM_ (putStrV v . showPosToken . mkPosToken) ts
            putStrLn err
            exitFailure
        Right tree -> do
            let annTree = SS.annotate tree
            let errs = SS.getErrs annTree
            unless (null errs) $ do
                putStrLn "\nStatic Semantics Analysis Failed:"
                case f of
                    Nothing -> mapM_ putStrLn errs
                    Just f  -> mapM_ (putStrLn . (\err -> f ++ ":" ++ err)) errs
                exitFailure
            putStrV v $ "\n[Pretty-Print of source]\n\n" ++ prt tree
            putStrV v "\n[Generated TAC]\n"
            print (TAC.genProgram annTree)
    where
        ts = myLexer s
        showPosToken ((l,c, _, _),t) = concat [ show l, ":", show c, "\t", show t ]

showTree :: (Show a, Print a) => Int -> a -> IO ()
showTree v tree = do
  putStrV v $ "\n[Abstract Syntax]\n\n" ++ show tree
  putStrV v $ "\n[Linearized tree]\n\n" ++ prt tree

usage :: IO ()
usage = do
  putStrLn $ unlines
    [ "usage: Call with one of the following argument combinations:"
    , "  --help          Display this help message."
    , "  (no arguments)  Parse stdin verbosely."
    , "  (files)         Parse content of files verbosely."
    , "  -s (files)      Silent mode. Only print TAC output"
    ]

main :: IO ()
main = do
  args <- getArgs
  case args of
    ["--help"] -> usage
    []         -> getContents >>= \s -> run 2 pDeclarations s Nothing
    "-s":fs    -> mapM_ (runFile 0 pDeclarations) fs
    fs         -> mapM_ (runFile 2 pDeclarations) fs

